// === Tab: mySketch ===
//music from Music by <a href="https://pixabay.com/users/kulakovka-47183261/?utm_source=link-attribution&utm_medium=referral&utm_campaign=music&utm_content=270241">Alehandro Vodnik</a> from <a href="https://pixabay.com/music//?utm_source=link-attribution&utm_medium=referral&utm_campaign=music&utm_content=270241">Pixabay</a>

let numThings = 200;
let things = [];

function preload()
{
	music = loadSound("https://openprocessing.org/sketch/2566933/files/lost-in-dreams-abstract-chill-downtempo-cinematic-future-beats-270241.mp3")
}

function setup() 
{
	createCanvas(windowWidth, windowHeight);
	background(0);
	colorMode(HSB);
	noStroke();
	for(let z = 0; z < 9; z++) 
	{
		for(let i = 0; i < numThings; i++) 
		{
			let x = map(i, 0, numThings, -30, width);
			let y = height/2 + sin(map(i,     0, numThings,     0, 2*PI)) * height/2;
			things.push(new Thing(x+z+random(-300,500), y-z*70, i));
		}
	}
	fft = new p5.FFT();
  fft.setInput(music);	
  music.play()
}
let B=60

lM = 0
M = 0
hM = 0
T = 0

function draw() 
{

	numThings=lM/2
	frameRate(B+10)
	background(B, 0.03);
	for(let z = 0; z < 9; z++) 
	{
		for (let i = 0; i < things.length; i++) 
		{
			things[i].update();
		}
	}

	let spectrum = fft.analyze();
	let bass, lowMid, mid, highMid, treble; 

	bass = fft.getEnergy("bass");
	lowMid = fft.getEnergy("lowMid");
	mid = fft.getEnergy("mid");
	highMid = fft.getEnergy("highMid");
	treble = fft.getEnergy("treble");

	 B = map(bass, 0, 300, -30, 60, true);
	 lM = map(lowMid, 0, 100, 0, 200, true);
	 M = map(mid, 0, 300, 0, 200, true);
	 hM = map(highMid, 0, 100, 0, 130, true);
	 T = map(treble, 0, 300, 0, 200, true);

}

class Thing 
{	
	constructor(x, y, i) 
	{
		this.x = x;
		this.y = y;	
		this.i = i;
		this.hue = map(this.i, 0, numThings, 0, 360);
		this.size = random(50, 100);
		this.c=round(random(1))
		this.c2=round(random(1))
	}
	update() 
	{
		this.x = (this.x + height/2/B) % width;
		this.size = random(M, hM/2);
		this.hue = (this.hue + 1) % 360;
		if(this.c2==0) 
		{
			noStroke()
			fill(this.hue, 35, B+30,B);
		}
		else
		{
			strokeWeight(2)
			noFill()
			stroke(this.hue, 35, B+30,B)
		}

		if(this.c==0) ellipse(this.x + noise(frameCount/100 + this.i) * 50, this.y, this.size-height/10);
		else rect(this.x + noise(frameCount/100 + this.i) * 50, this.y, this.size-height/10);
	}
}

